 private String hash(String value)throws Exception{byte[] data=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));StringBuilder out=new StringBuilder();for(byte b:data)out.append(String.format(Locale.ROOT,"%02x",b&255));Arrays.fill(data,(byte)0);return out.toString();}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(Color.WHITE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);store=new VaultStore(this);bio=new BiometricVault(this);lastTouch=System.currentTimeMillis();connectivity=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);networkCallback=new ConnectivityManager.NetworkCallback(){@Override public void onAvailable(Network network){runOnUiThread(()->autoSync(250));}};try{connectivity.registerDefaultNetworkCallback(networkCallback);}catch(Exception ignored){}login();timer.post(tick);}
 private final Runnable tick=new Runnable(){public void run(){long now=System.currentTimeMillis();if(session!=null&&now-lastTouch>300000)lock();else if(session!=null&&now-lastAutoSync>60000)autoSync(0);if(!destroyed)timer.postDelayed(this,1000);}};
